var ENT=[["Trifacta", "Visual wrangling suggesting transforms."], ["Talend", "Open-source data integration studio."], ["Pentaho Kettle", "ETL with a visual designer."], ["Apache NiFi", "Flow-based data routing and transform."], ["pandas", "Python's DataFrame library; the workhorse of tabular cleaning and reshaping."], ["OpenRefine", "A free tool for messy-data wrangling: clustering, faceting, reconciliation."], ["dbt", "SQL-based transformation with testing and docs; the analytics-engineering standard."]];
var TECH=[["Deduplication", "Finding and merging near-duplicate records via keys or fuzzy matching."], ["Missing-value imputation", "Filling gaps with means, medians or model predictions - and flagging them."], ["Outlier detection", "Z-scores, IQR fences and isolation forests surfacing suspicious values."], ["Normalization", "Scaling features with min-max or z-score so models and joins behave."], ["Type coercion", "Parsing strings into dates and numbers with explicit failure handling."], ["Regex extraction", "Pulling structured fields out of semi-structured text."], ["Canonicalization", "Mapping variants like NYC and New York to one canonical form."], ["Referential checks", "Verifying foreign keys actually resolve before loading."], ["Idempotent transforms", "Re-running a cleaning job yields identical output."], ["Data contracts", "Producer and consumer agreements on schema and quality, enforced in CI."]];
